import sys
MOD = 998244353

def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n = data[0]
    arr = data[1:]
    factors = []
    primes = set()

    for a in arr:
        x = a
        fs = {}
        d = 2
        while d * d <= x:
            if x % d == 0:
                e = 0
                while x % d == 0:
                    x //= d
                    e += 1
                fs[d] = e
                primes.add(d)
            d += 1 if d == 2 else 2
        if x > 1:
            fs[x] = 1
            primes.add(x)
        factors.append(fs)

    answer = 1
    for p in primes:
        dp = {0: 1}
        i = 1  # number of vertices represented so far
        for fs in factors:
            e = fs.get(p, 0)
            next_dp = {}
            choices = (0,) if e == 0 else (e, -e)
            for height, value in dp.items():
                for delta in choices:
                    z = height + delta
                    if z >= 0:
                        new_height = z
                        multiplier = pow(p, z, MOD)
                    else:
                        # A new minimum shifts each of the i old heights up by -z.
                        new_height = 0
                        multiplier = pow(p, i * (-z), MOD)
                    next_dp[new_height] = (next_dp.get(new_height, 0) + value * multiplier) % MOD
            dp = next_dp
            i += 1
        answer = answer * (sum(dp.values()) % MOD) % MOD

    print(answer)

