class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        MOD = 10**9 + 7
        n = len(s)

        # Binomial coefficients for choosing the remaining set bits.
        comb = [[0] * (n + 1) for _ in range(n + 1)]
        for i in range(n + 1):
            comb[i][0] = comb[i][i] = 1
            for j in range(1, i):
                comb[i][j] = (comb[i - 1][j - 1] + comb[i - 1][j]) % MOD

        # ways[t] is the number of length-n bit strings less than s
        # that have exactly t set bits.
        ways = [0] * (n + 1)
        used = 0
        for idx, ch in enumerate(s):
            if ch == '1':
                rem = n - idx - 1
                for total in range(1, n + 1):
                    need = total - used
                    if 0 <= need <= rem:
                        ways[total] = (ways[total] + comb[rem][need]) % MOD
                used += 1

        ans = 0
        for total in range(1, n + 1):
            # A number with 'total' set bits takes one operation to become
            # total, then this many more operations to reach 1.
            x = total
            steps = 0
            while x > 1:
                x = x.bit_count()
                steps += 1
            if steps <= k - 1:
                ans = (ans + ways[total]) % MOD
        return ans

