import sys
from collections import deque

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    it = iter(data)
    N, M, Q = next(it), next(it), next(it)
    people = [(next(it)-1, next(it)-1) for _ in range(M)]
    queries = [(next(it)-1, next(it)-1) for _ in range(Q)]
    out = []
    for L, R in queries:
        parent = list(range(N))
        size = [1] * N
        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x
        for i in range(L, R+1):
            a, b = people[i]
            a, b = find(a), find(b)
            if a != b:
                if size[a] < size[b]:
                    a, b = b, a
                parent[b] = a
                size[a] += size[b]
        # Compress all vertices after the equality unions.
        rep = [find(x) for x in range(N)]
        edges = []
        indeg = [0] * N
        for i in range(L, R+1):
            s, t = people[i]
            if s < t:
                u = rep[s]
                for x in range(s+1, t):
                    v = rep[x]
                    if u != v:
                        edges.append((u, v))
                        indeg[v] += 1
            else:
                u = rep[t]
                for x in range(t+1, s):
                    v = rep[x]
                    if u != v:
                        edges.append((v, u))
                        indeg[u] += 1
        # Build adjacency only for representatives with constraints.
        adj = [[] for _ in range(N)]
        for u, v in edges:
            adj[u].append(v)
        q = deque(x for x in range(N) if rep[x] == x and indeg[x] == 0)
        done = 0
        while q:
            u = q.popleft()
            done += 1
            for v in adj[u]:
                indeg[v] -= 1
                if indeg[v] == 0:
                    q.append(v)
        comps = sum(1 for x in range(N) if rep[x] == x)
        out.append('Yes' if done == comps else 'No')
    sys.stdout.write('\n'.join(out))

if __name__ == '__main__':
    main()

