    # Incoming and outgoing neighbors, grouped by edge label.
    incoming = [[[] for _ in range(26)] for _ in range(n)]
    outgoing = [[[] for _ in range(26)] for _ in range(n)]
    edges = []

    for u in range(n):
        for v, ch in enumerate(graph[u]):
            if ch != '-':
                c = ord(ch) - 97
                outgoing[u][c].append(v)
                incoming[v][c].append(u)
                edges.append((u, v))

    dist = [[-1] * n for _ in range(n)]
    q = deque()

    # A palindrome can have an empty center or a one-edge center.
    for u in range(n):
        dist[u][u] = 0
        q.append((u, u))
    for u, v in edges:
        if dist[u][v] == -1:
            dist[u][v] = 1
            q.append((u, v))

    while q:
        u, v = q.popleft()
        nd = dist[u][v] + 2
        for c in range(26):
            left = incoming[u][c]
            right = outgoing[v][c]
            for a in left:
                row = dist[a]
                for b in right:
                    if row[b] == -1:
                        row[b] = nd
                        q.append((a, b))

    sys.stdout.write('\n'.join(' '.join(map(str, row)) for row in dist))

